def human_size(n):
    """Human-readable byte size."""
    n = float(n)
    for unit in ["B", "KB", "MB", "GB", "TB"]:
        if n < 1024 or unit == "TB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def scenario_of(name):
    """Leading scenario code in a filename (e.g. 'QCL-1'), or '' if none."""
    m = re.match(r"([A-Z]+-\d+)", name)
    return m.group(1) if m else ""


def folder_table(folder, pattern="*"):
    """One row per file in `folder` matching `pattern`: name, scenario, size."""
    rows = [
        {"file": f.name, "scenario": scenario_of(f.name),
         "size": human_size(f.stat().st_size)}
        for f in sorted(Path(folder).glob(pattern)) if f.is_file()
    ]
    return pd.DataFrame(rows)

def version_code(filename: str) -> str:
    """Extract the scenario code (e.g. 'LGR-1', 'QCL-4') from a filename.

    The code is the leading token of the filename, before the first underscore.
    """
    match = re.match(r"([A-Z]+-\d+)_", filename)
    if not match:
        raise ValueError(f"Could not extract a version code from: {filename}")
    return match.group(1)


